shopify.query:
query AdsHeartbeatSep13MorningOrderCounts {
  shop { id name ianaTimezone }
  allNew: ordersCount(query:"created_at:>='2026-09-13T02:52:53Z' created_at:<'2026-09-13T06:54:26Z'",limit:null) { count precision }
  webNonTest: ordersCount(query:"created_at:>='2026-09-13T02:52:53Z' created_at:<'2026-09-13T06:54:26Z' source_name:web test:false",limit:null) { count precision }
  paidWebNonTest: ordersCount(query:"created_at:>='2026-09-13T02:52:53Z' created_at:<'2026-09-13T06:54:26Z' source_name:web test:false financial_status:paid",limit:null) { count precision }
}
